mapper.select:
SELECT r.reta_batch_id AS retaBatchId, r.trace_code AS traceCode, r.product_code AS productCode, r.batch_no AS batchNo, r.breed AS breed, r.product_type AS productType, -- 可为空的字符串统一 COALESCE 成空串：MySQL 会直接省略 NULL 列， -- 导致前端拿到的对象时有时无这些 key，形状不稳定 COALESCE(r.product_form, '冻虾') AS productForm, COALESCE(r.spec_grade, '') AS specGrade, COALESCE(r.quality_status, 0) AS qualityStatus, r.price AS price, r.image_url AS imageUrl, r.trace_time AS traceTime, rn.name AS retailerName, COALESCE(fn.name, '') AS originFarmName, COALESCE(fn.address, '') AS originAddress, COALESCE(fm.source_type, '') AS sourceType, COALESCE(fm.breed_stage, '') AS breedStage, COALESCE(pn.prov_name, '') AS originProvName, COALESCE(cn.city_name, '') AS originCityName FROM reta_batch r LEFT JOIN whol_batch w ON w.batch_no = r.up_batch_no AND w.node_id = r.up_node_id LEFT JOIN froz_batch f ON f.batch_no = w.up_batch_no AND f.node_id = w.up_node_id LEFT JOIN farm_batch fm ON fm.batch_no = f.up_batch_no AND fm.node_id = f.up_node_id LEFT JOIN node_info rn ON rn.node_id = r.node_id LEFT JOIN node_info fn ON fn.node_id = fm.node_id LEFT JOIN province pn ON pn.prov_id = rn.prov_id LEFT JOIN city cn ON cn.city_id = rn.city_id WHERE
AND (r.breed LIKE CONCAT('%', #{keyword}, '%') OR r.product_type LIKE CONCAT('%', #{keyword}, '%') OR r.product_code LIKE CONCAT('%', #{keyword}, '%') OR r.trace_code LIKE CONCAT('%', #{keyword}, '%'))
AND r.product_form = #{form}
AND rn.prov_id = #{provId}
ORDER BY r.trace_time DESC, r.reta_batch_id DESC
